from django.conf import settings
from django.db import models
class Plan(models.Model): name=models.CharField(max_length=80,unique=True); code=models.SlugField(unique=True); monthly_price=models.DecimalField(max_digits=12,decimal_places=2,default=0); yearly_price=models.DecimalField(max_digits=12,decimal_places=2,default=0); transaction_limit=models.PositiveIntegerField(null=True,blank=True); features=models.JSONField(default=list); is_active=models.BooleanField(default=True)
class Subscription(models.Model): user=models.ForeignKey(settings.AUTH_USER_MODEL,on_delete=models.CASCADE); plan=models.ForeignKey(Plan,on_delete=models.PROTECT); status=models.CharField(max_length=15,default="trial"); started_at=models.DateTimeField(auto_now_add=True); ends_at=models.DateTimeField(null=True,blank=True); cancel_at_period_end=models.BooleanField(default=False)
class BillingPayment(models.Model): subscription=models.ForeignKey(Subscription,on_delete=models.CASCADE); provider=models.CharField(max_length=50); provider_reference=models.CharField(max_length=150,unique=True); amount=models.DecimalField(max_digits=12,decimal_places=2); currency=models.CharField(max_length=3,default="KES"); status=models.CharField(max_length=30); created_at=models.DateTimeField(auto_now_add=True)
